-- TomoModForever 1.2.9 release notes.

TomoMod_RegisterLocale("enUS", {
    ["wn_129_loot"] = "New - Dungeon codex, Loot button: a window of its own, with a scroll bar and a Back button to the codex, listing what each boss of the dungeon (or wing) drops, with the item tooltip on hover, shift-click to link it and ctrl-click for the dressing room. \"For me\" keeps only what your class uses: its own armour type (leather then mail at 40 for hunters and shamans, mail then plate at 40 for warriors and paladins), its weapons, shields and relics. The scroll bar works with the mouse alone: arrows, track and draggable thumb. Item tooltips also show \"Loot: boss (dungeon)\". Loot data from ForeverLoot by Ethan Elliott, used with his permission. Thank you!",
    ["wn_129_triage"] = "Fixed - Bags: items with an apostrophe in their name (\"Crisp Spider Meat\" in French) are now recognised as wanted by your quest log: gold border, and never suggested to throw away.",
    ["wn_129_forever"] = "New - Unit frames, \"Forever\" look (Frames > Shared style > Frame style): a name strip in the class colour (reaction colour for NPCs), health and power centred, bronze and gold border and a level medallion, without portraits. Player, target, target of target, pet and focus. \"TMF\" stays the default look; you can switch at any time. Optional round portrait (\"Forever: show the portrait\"). Its sizes are set per frame in Frames > Shared style > Forever sizes.",
    ["opt_obj_tracker_group_zone"] = "Group quests by zone (with categories)",
    ["ot_zone_other"] = "Other",
    ["wn_129_zones"] = "New - Quest tracker: unfinished quests are now grouped by zone (Elwynn Forest, Westfall...) under small gold sub-headers with their count, in the order of your quest log. Quests ready to turn in keep their own section. Option: \"Group quests by zone\". Click a zone to fold it, click again to unfold it.",
})

TomoMod_RegisterLocale("frFR", {
    ["wn_129_loot"] = "Nouveau - Codex des donjons, bouton Butin : une fenêtre à part, avec une barre de défilement et un bouton Retour vers le codex, qui liste ce que lâche chaque boss du donjon (ou de l'aile), avec l'infobulle de l'objet au survol, Maj-clic pour le lier et Ctrl-clic pour la cabine d'essayage. \"Pour moi\" ne garde que ce qui sert à ta classe : ton type d'armure (cuir puis maille au niveau 40 pour chasseur et chaman, maille puis plaque au niveau 40 pour guerrier et paladin), tes armes, boucliers et reliques. La barre de défilement s'utilise entièrement à la souris : flèches, piste et curseur à tirer. Les infobulles d'objets affichent aussi \"Butin : boss (donjon)\". Données de butin issues de ForeverLoot d'Ethan Elliott, utilisées avec son accord. Merci à lui !",
    ["wn_129_triage"] = "Corrigé - Sacs : les objets avec une apostrophe dans leur nom (\"Chair croustillante d'araignée\") sont maintenant reconnus comme demandés par ton journal de quêtes : contour doré, et jamais proposés à jeter.",
    ["wn_129_forever"] = "Nouveau - Cadres d'unité, style \"Forever\" (Cadres > Style commun > Style des cadres) : bandeau de nom aux couleurs de la classe (ou de la réaction pour les PNJ), vie et ressource centrées, cadre bronze et or et médaillon de niveau, sans portrait. Joueur, cible, cible de la cible, familier et focus. \"TMF\" reste le style par défaut, tu peux changer à tout moment. Portrait rond en option (\"Forever : afficher le portrait\"). Ses tailles se règlent cadre par cadre dans Cadres > Style commun > Tailles Forever.",
    ["opt_obj_tracker_group_zone"] = "Regrouper les quêtes par zone (avec les catégories)",
    ["ot_zone_other"] = "Autres",
    ["wn_129_zones"] = "Nouveau - Suivi des quêtes : les quêtes en cours sont maintenant regroupées par zone (Forêt d'Elwynn, Marche de l'Ouest...) sous de petits sous-titres dorés avec leur nombre, dans l'ordre de ton journal. Les quêtes prêtes à rendre gardent leur section. Option : \"Regrouper les quêtes par zone\". Clique sur une zone pour la réduire, reclique pour la déplier.",
})

TomoMod_RegisterLocale("deDE", {
    ["wn_129_loot"] = "Neu - Dungeon-Kodex, Schaltfläche Beute: ein eigenes Fenster mit Bildlaufleiste und Zurück-Taste zum Kodex, das zeigt, was jeder Boss des Dungeons (oder Flügels) fallen lässt, mit Gegenstands-Tooltip, Umschalt-Klick zum Verlinken und Strg-Klick für die Anprobe. \"Für mich\" zeigt nur, was deine Klasse nutzt: ihren Rüstungstyp (Leder, ab Stufe 40 Kette für Jäger und Schamanen; Kette, ab 40 Platte für Krieger und Paladine), ihre Waffen, Schilde und Reliquien. Die Bildlaufleiste geht ganz mit der Maus: Pfeile, Leiste und ziehbarer Regler. Gegenstands-Tooltips zeigen auch \"Beute: Boss (Dungeon)\". Beutedaten aus ForeverLoot von Ethan Elliott, mit seiner Erlaubnis verwendet. Danke!",
    ["wn_129_triage"] = "Behoben - Taschen: Gegenstände mit Apostroph im Namen werden jetzt als von deinem Questlog verlangt erkannt: goldener Rahmen, nie zum Wegwerfen vorgeschlagen.",
    ["wn_129_forever"] = "Neu - Einheitenfenster, Stil \"Forever\" (Fenster > Gemeinsamer Stil > Fensterstil): Namensleiste in Klassenfarbe (Reaktionsfarbe bei NSCs), Leben und Ressource zentriert, Rahmen in Bronze und Gold und ein Stufenmedaillon, ohne Porträts. Spieler, Ziel, Ziel des Ziels, Begleiter und Fokus. \"TMF\" bleibt der Standard; jederzeit umschaltbar. Rundes Porträt als Option (\"Forever: Porträt anzeigen\"). Seine Größen werden pro Fenster unter Fenster > Gemeinsamer Stil > Forever-Größen eingestellt.",
    ["opt_obj_tracker_group_zone"] = "Quests nach Zone gruppieren (mit Kategorien)",
    ["ot_zone_other"] = "Andere",
    ["wn_129_zones"] = "Neu - Questverfolgung: Offene Quests sind jetzt nach Zone gruppiert (Wald von Elwynn, Westfall...), unter kleinen goldenen Untertiteln mit Anzahl, in der Reihenfolge deines Questlogs. Abgabebereite Quests behalten ihren Abschnitt. Option: \"Quests nach Zone gruppieren\". Klick auf eine Zone klappt sie ein, ein weiterer Klick wieder aus.",
})

TomoMod_RegisterLocale("esES", {
    ["wn_129_loot"] = "Nuevo - Códice de mazmorras, botón Botín: una ventana propia, con barra de desplazamiento y un botón Volver al códice, que muestra lo que suelta cada jefe de la mazmorra (o del ala), con la descripción del objeto al pasar el ratón, Mayús-clic para enlazarlo y Ctrl-clic para el probador. \"Para mí\" deja solo lo que usa tu clase: su tipo de armadura (cuero y malla desde el nivel 40 para cazadores y chamanes; malla y placas desde el 40 para guerreros y paladines), sus armas, escudos y reliquias. La barra de desplazamiento funciona solo con el ratón: flechas, pista y control deslizante. Las descripciones de objetos muestran también \"Botín: jefe (mazmorra)\". Datos de botín de ForeverLoot de Ethan Elliott, usados con su permiso. ¡Gracias!",
    ["wn_129_triage"] = "Corregido - Bolsas: los objetos con apóstrofo en su nombre ahora se reconocen como pedidos por tu registro de misiones: borde dorado, y nunca se proponen para tirar.",
    ["wn_129_forever"] = "Nuevo - Marcos de unidad, estilo \"Forever\" (Marcos > Estilo común > Estilo de marcos): franja de nombre con el color de la clase (color de reacción para los PNJ), vida y recurso centrados, borde de bronce y oro y medallón de nivel, sin retratos. Jugador, objetivo, objetivo del objetivo, mascota y foco. \"TMF\" sigue siendo el estilo por defecto; se puede cambiar en cualquier momento. Retrato redondo opcional (\"Forever: mostrar el retrato\"). Sus tamaños se ajustan marco a marco en Marcos > Estilo común > Tamaños Forever.",
    ["opt_obj_tracker_group_zone"] = "Agrupar misiones por zona (con categorías)",
    ["ot_zone_other"] = "Otras",
    ["wn_129_zones"] = "Nuevo - Seguimiento de misiones: las misiones en curso se agrupan ahora por zona (Bosque de Elwynn, Páramos de Poniente...) bajo pequeños subtítulos dorados con su número, en el orden de tu registro. Las misiones listas para entregar mantienen su sección. Opción: \"Agrupar misiones por zona\". Haz clic en una zona para plegarla y otra vez para desplegarla.",
})

TomoMod_RegisterLocale("itIT", {
    ["wn_129_loot"] = "Nuovo - Codice delle spedizioni, pulsante Bottino: una finestra a parte, con barra di scorrimento e un pulsante Indietro verso il codice, che mostra cosa lascia ogni boss della spedizione (o dell'ala), con il tooltip dell'oggetto, Maiusc-clic per collegarlo e Ctrl-clic per il camerino. \"Per me\" tiene solo ciò che usa la tua classe: il suo tipo di armatura (cuoio poi maglia dal livello 40 per cacciatori e sciamani; maglia poi piastre dal 40 per guerrieri e paladini), armi, scudi e reliquie. La barra di scorrimento si usa anche solo col mouse: frecce, binario e cursore trascinabile. I tooltip degli oggetti mostrano anche \"Bottino: boss (spedizione)\". Dati del bottino da ForeverLoot di Ethan Elliott, usati con il suo permesso. Grazie!",
    ["wn_129_triage"] = "Corretto - Borse: gli oggetti con un apostrofo nel nome ora sono riconosciuti come richiesti dal registro missioni: bordo dorato, e mai proposti da buttare.",
    ["wn_129_forever"] = "Nuovo - Riquadri delle unità, stile \"Forever\" (Riquadri > Stile comune > Stile dei riquadri): fascia del nome nel colore della classe (colore di reazione per i PNG), vita e risorsa centrate, bordo bronzo e oro e medaglione del livello, senza ritratti. Giocatore, bersaglio, bersaglio del bersaglio, famiglio e focus. \"TMF\" resta lo stile predefinito; si cambia quando vuoi. Ritratto rotondo opzionale (\"Forever: mostra il ritratto\"). Le sue dimensioni si regolano riquadro per riquadro in Riquadri > Stile comune > Dimensioni Forever.",
    ["opt_obj_tracker_group_zone"] = "Raggruppa le missioni per zona (con le categorie)",
    ["ot_zone_other"] = "Altre",
    ["wn_129_zones"] = "Nuovo - Tracciamento missioni: le missioni in corso ora sono raggruppate per zona (Foresta di Elwynn, Marche Occidentali...) sotto piccoli sottotitoli dorati con il loro numero, nell'ordine del registro. Le missioni da consegnare tengono la loro sezione. Opzione: \"Raggruppa le missioni per zona\". Clicca su una zona per ridurla, clicca di nuovo per riaprirla.",
})

TomoMod_RegisterLocale("ptBR", {
    ["wn_129_loot"] = "Novo - Códice de masmorras, botão Saque: uma janela própria, com barra de rolagem e um botão Voltar para o códice, que mostra o que cada chefe da masmorra (ou ala) derruba, com a dica do item ao passar o mouse, Shift-clique para criar o link e Ctrl-clique para o provador. \"Para mim\" mostra só o que sua classe usa: seu tipo de armadura (couro e depois malha no nível 40 para caçadores e xamãs; malha e depois placas no 40 para guerreiros e paladinos), suas armas, escudos e relíquias. A barra de rolagem funciona só com o mouse: setas, trilho e marcador arrastável. As dicas de itens também mostram \"Saque: chefe (masmorra)\". Dados de saque do ForeverLoot de Ethan Elliott, usados com a permissão dele. Obrigado!",
    ["wn_129_triage"] = "Corrigido - Bolsas: itens com apóstrofo no nome agora são reconhecidos como pedidos pelo registro de missões: borda dourada, e nunca sugeridos para descartar.",
    ["wn_129_forever"] = "Novo - Quadros de unidade, estilo \"Forever\" (Quadros > Estilo comum > Estilo dos quadros): faixa de nome na cor da classe (cor de reação para PNJs), vida e recurso centralizados, borda bronze e dourada e medalhão de nível, sem retratos. Jogador, alvo, alvo do alvo, mascote e foco. \"TMF\" continua o estilo padrão; dá para trocar a qualquer momento. Retrato redondo opcional (\"Forever: mostrar o retrato\"). Seus tamanhos se ajustam quadro a quadro em Quadros > Estilo comum > Tamanhos Forever.",
    ["opt_obj_tracker_group_zone"] = "Agrupar missões por zona (com as categorias)",
    ["ot_zone_other"] = "Outras",
    ["wn_129_zones"] = "Novo - Rastreador de missões: as missões em andamento agora ficam agrupadas por zona (Floresta de Elwynn, Cerro Oeste...) sob pequenos subtítulos dourados com a contagem, na ordem do seu registro. Missões prontas para entregar mantêm a própria seção. Opção: \"Agrupar missões por zona\". Clique numa zona para recolhê-la e de novo para expandi-la.",
